# -*- coding: utf-8 -*-
"""
start_safe.py  —  запуск ботов UA ART COMPANY с защитой от TimedOut.
БЕЗ КОНСОЛИ и без правки твоих файлов.

Как включить:
  1) Загрузить этот файл в /home/Carix/   (Files -> Upload a file)
  2) Вкладка Tasks -> у задачи нажать карандаш (Edit)
     и заменить команду на:
         python3.10 /home/Carix/start_safe.py
  3) Нажать Restart / галочку.

Ни один твой файл не меняется. Чтобы вернуть как было — просто верни
в задаче прежнюю команду: python3.10 /home/Carix/run_all.py

Что делает:
  - поднимает таймауты Telegram (5 c -> 60/120/180 c);
  - повторяет отправку до 4 раз при обрыве связи;
  - не присылает владельцу «Сбой во внутреннем боте» на сетевые таймауты;
  - после этого обычным образом запускает run_all.py.
"""

import os
import sys
import time
import asyncio
import functools
import logging
import runpy
import shutil

BASE = "/home/Carix"
TARGET = os.path.join(BASE, "run_all.py")

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s %(levelname)s %(name)s: %(message)s",
)
log = logging.getLogger("start_safe")

# --- таймауты и повторы ----------------------------------------------------

READ_TIMEOUT = 60
WRITE_TIMEOUT_TEXT = 60
WRITE_TIMEOUT_MEDIA = 180
CONNECT_TIMEOUT = 30
POOL_TIMEOUT = 15

RETRIES = 3
PAUSE = 1.5

TEXT_METHODS = (
    "send_message",
    "edit_message_text",
    "edit_message_caption",
    "edit_message_reply_markup",
    "edit_message_media",
    "delete_message",
)

# нажатие кнопки подтверждается за секунды — повторять нельзя
SILENT_METHODS = ("answer_callback_query",)

MEDIA_METHODS = (
    "send_photo",
    "send_video",
    "send_document",
    "send_audio",
    "send_animation",
    "send_media_group",
)


def _bump(value, floor):
    """None значит «без ограничения» — не трогаем. Маленькое значение поднимаем."""
    if value is None:
        return None
    try:
        return max(float(value), float(floor))
    except (TypeError, ValueError):
        return floor


def patch_request_timeouts():
    """Заводские 5 секунд в HTTPXRequest заменяем на человеческие."""
    from telegram.request import HTTPXRequest

    orig = HTTPXRequest.__init__
    if getattr(orig, "_ns_wrapped", False):
        return

    @functools.wraps(orig)
    def inner(self, *args, **kwargs):
        # ГЛАВНОЕ: по умолчанию соединение с Telegram всего одно.
        # Пока уходит альбом фото, все остальные запросы стоят в очереди
        # и умирают по таймауту. Даём 16 параллельных соединений.
        try:
            size = int(kwargs.get("connection_pool_size") or 1)
        except (TypeError, ValueError):
            size = 1
        kwargs["connection_pool_size"] = max(size, 16)

        kwargs["read_timeout"] = _bump(kwargs.get("read_timeout", 5), READ_TIMEOUT)
        kwargs["write_timeout"] = _bump(kwargs.get("write_timeout", 5), WRITE_TIMEOUT_TEXT)
        kwargs["connect_timeout"] = _bump(kwargs.get("connect_timeout", 5), CONNECT_TIMEOUT)
        kwargs["pool_timeout"] = _bump(kwargs.get("pool_timeout", 1), POOL_TIMEOUT)
        try:
            return orig(self, *args, **kwargs)
        except TypeError:
            # версия библиотеки не знает таких аргументов — идём как есть
            for k in (
                "read_timeout", "write_timeout", "connect_timeout",
                "pool_timeout", "connection_pool_size",
            ):
                kwargs.pop(k, None)
            return orig(self, *args, **kwargs)

    inner._ns_wrapped = True
    HTTPXRequest.__init__ = inner
    log.info("таймауты соединения подняты")


def _wrap_send(orig, is_media, errors):
    TimedOut, NetworkError, RetryAfter = errors

    @functools.wraps(orig)
    async def inner(self, *args, **kwargs):
        args, kwargs = fix_split_text(orig.__name__, args, kwargs)
        if orig.__name__ == "send_media_group":
            args, kwargs = _dopisat_video(args, kwargs)
        kwargs.setdefault("read_timeout", READ_TIMEOUT)
        kwargs.setdefault("connect_timeout", CONNECT_TIMEOUT)
        kwargs.setdefault(
            "write_timeout", WRITE_TIMEOUT_MEDIA if is_media else WRITE_TIMEOUT_TEXT
        )

        last = None
        for attempt in range(1, RETRIES + 1):
            try:
                # тот же самый файл уже уходил — отправляем по id, без заливки
                sent_id = None
                if orig.__name__ == "send_document":
                    raw = _doc_bytes(kwargs.get("document") or (args[1] if len(args) > 1 else None))
                    if raw:
                        sig = "doc:" + hashlib.md5(raw).hexdigest()
                        cached = _cache_get(sig)
                        if cached:
                            kwargs.pop("document", None)
                            if len(args) > 1:
                                args = (args[0],) + (cached.decode("utf-8"),) + tuple(args[2:])
                            else:
                                kwargs["document"] = cached.decode("utf-8")
                            log.info("файл взят из кэша, без перезаливки")
                        else:
                            sent_id = sig

                result = await orig(self, *args, **kwargs)

                if orig.__name__ == "send_document":
                    try:
                        if sent_id and getattr(result, "document", None):
                            _cache_put(sent_id, result.document.file_id.encode("utf-8"))
                    except Exception:
                        pass
                    asyncio.create_task(_videos_after_html(self, result))
                return result
            except RetryAfter as e:
                last = e
                wait = float(getattr(e, "retry_after", 3)) + 1
                log.warning("флуд-контроль на %s, ждём %.0f c", orig.__name__, wait)
                await asyncio.sleep(wait)
            except (TimedOut, NetworkError) as e:
                last = e
                if attempt == RETRIES:
                    break
                wait = PAUSE * attempt
                log.warning(
                    "сеть подвела на %s, попытка %d из %d, пауза %.0f c",
                    orig.__name__, attempt, RETRIES, wait,
                )
                await asyncio.sleep(wait)
            except TypeError:
                for k in ("read_timeout", "write_timeout", "connect_timeout"):
                    kwargs.pop(k, None)
                return await orig(self, *args, **kwargs)
        raise last

    inner._ns_wrapped = True
    return inner


async def _videos_after_html(bot, message):
    """HTML собирается только с фото — видео досылаем следом в чат."""
    try:
        doc = getattr(message, "document", None)
        name = getattr(doc, "file_name", "") or ""
        found = re.search(r"(UA-\d+)\.html$", name, re.IGNORECASE)
        if not found:
            return
        number = found.group(1)

        cols = set(_car_columns())
        if "videos" not in cols or "auto_number" not in cols:
            return
        rows = _rows(
            "SELECT videos FROM cars WHERE auto_number = ? LIMIT 1", (number,)
        )
        if not rows:
            return
        videos = _ids(rows[0].get("videos"))
        if not videos:
            log.info("у карточки %s видео нет", number)
            return
        if time.time() - VIDEO_V_ALBOME.get(number, 0) < 120:
            log.info("видео по %s уже внутри карточки — не дублируем", number)
            return

        from telegram import InputMediaVideo

        chat_id = message.chat_id
        await bot.send_message(chat_id, "Видео по карточке %s — %d шт." % (number, len(videos)))
        for i in range(0, len(videos), 10):
            chunk = videos[i:i + 10]
            if len(chunk) == 1:
                await bot.send_video(chat_id, chunk[0])
            else:
                await bot.send_media_group(chat_id, [InputMediaVideo(v) for v in chunk])
            await asyncio.sleep(ALBUM_PAUSE)
        log.info("досланы видео по карточке %s: %d", number, len(videos))
    except Exception as e:
        log.warning("не удалось дослать видео: %r", e)


# --- кэш: не качаем и не заливаем одно и то же дважды ----------------------

import hashlib

CACHE_DIR = os.path.join(BASE, ".ns_cache")


def _cache_path(key):
    safe = hashlib.md5(str(key).encode("utf-8")).hexdigest()
    return os.path.join(CACHE_DIR, safe + ".bin")


def _cache_get(key):
    try:
        path = _cache_path(key)
        if os.path.exists(path):
            with open(path, "rb") as fh:
                return fh.read()
    except Exception:
        pass
    return None


def _cache_put(key, data):
    try:
        os.makedirs(CACHE_DIR, exist_ok=True)
        with open(_cache_path(key), "wb") as fh:
            fh.write(data)
    except Exception as e:
        log.warning("кэш не записался: %r", e)


def patch_download_cache():
    """Каждый кадр скачивается из Telegram один раз за всё время."""
    from telegram import File

    for name in ("download_as_bytearray", "download_to_memory"):
        orig = File.__dict__.get(name)
        if orig is None or getattr(orig, "_ns_wrapped", False):
            continue

        @functools.wraps(orig)
        async def inner(self, *args, __orig=orig, __name=name, **kwargs):
            key = getattr(self, "file_unique_id", None) or getattr(self, "file_id", "")
            data = _cache_get(key) if key else None

            if __name == "download_as_bytearray":
                if data is not None:
                    return bytearray(data)
                result = await __orig(self, *args, **kwargs)
                if key and result:
                    _cache_put(key, bytes(result))
                return result

            # download_to_memory(out) — пишем в переданный буфер
            out = args[0] if args else kwargs.get("out")
            if data is not None and out is not None:
                out.write(data)
                return None
            result = await __orig(self, *args, **kwargs)
            try:
                if key and out is not None:
                    pos = out.tell()
                    out.seek(0)
                    _cache_put(key, out.read())
                    out.seek(pos)
            except Exception:
                pass
            return result

        inner._ns_wrapped = True
        setattr(File, name, inner)
    log.info("кэш скачанных кадров включён")


def _doc_bytes(document):
    """Достаёт байты собранного файла, если это возможно."""
    if isinstance(document, (bytes, bytearray)):
        return bytes(document)
    data = getattr(document, "input_file_content", None)
    if isinstance(data, (bytes, bytearray)):
        return bytes(data)
    return None


# --- видео внутри карточки, сразу под фото ---------------------------------
#
# Telegram разрешает класть фото и видео в один альбом. Ловим последний
# альбом карточки и дописываем в него ролики: они оказываются внутри
# галереи, под фотографиями. Ограничение в 20 МБ здесь не работает —
# файл уже лежит в Telegram, бот его не скачивает.

_KARTY = {"kogda": 0.0, "spisok": []}
VIDEO_V_ALBOME = {}          # номер карточки -> когда видео уже ушли
NASTROYKA = {}               # чат -> шаг настройки помощника


def _karty():
    """Список карточек с медиа, обновляется раз в минуту."""
    if time.time() - _KARTY["kogda"] < 60 and _KARTY["spisok"]:
        return _KARTY["spisok"]
    try:
        cols = set(_car_columns())
        nuzhno = [c for c in ("auto_number", "photos", "videos", "hidden_photos")
                  if c in cols]
        if "photos" not in nuzhno or "videos" not in nuzhno:
            return []
        rows = _rows("SELECT %s FROM cars" % ", ".join(nuzhno))
        spisok = []
        for d in rows:
            hidden = set(_ids(d.get("hidden_photos")))
            foto = [p for p in _ids(d.get("photos")) if p not in hidden]
            video = _ids(d.get("videos"))
            if foto and video:
                spisok.append({
                    "nomer": d.get("auto_number") or "",
                    "foto": foto,
                    "video": video,
                })
        _KARTY["spisok"] = spisok
        _KARTY["kogda"] = time.time()
        return spisok
    except Exception as e:
        log.warning("не прочитал карточки: %r", e)
        return []


def _dopisat_video(args, kwargs):
    """Если это последний альбом фото карточки — дописываем в него видео."""
    try:
        media = kwargs.get("media")
        iz_kwargs = media is not None
        if media is None and len(args) > 1:
            media = args[1]
        if not media or not isinstance(media, (list, tuple)) or len(media) >= 10:
            return args, kwargs

        ids = []
        for m in media:
            fid = getattr(m, "media", None)
            tip = getattr(m, "type", "")
            if not isinstance(fid, str) or tip not in ("photo", ""):
                return args, kwargs          # альбом не из чистых фото
            ids.append(fid)
        if not ids:
            return args, kwargs

        for karta in _karty():
            if ids[-1] != karta["foto"][-1]:
                continue                     # не последний альбом карточки
            if not set(ids) & set(karta["foto"]):
                continue
            nomer = karta["nomer"]

            from telegram import InputMediaVideo
            mesto = 10 - len(media)
            roliki = karta["video"][:mesto]
            if not roliki:
                return args, kwargs

            novoe = list(media) + [InputMediaVideo(v) for v in roliki]
            VIDEO_V_ALBOME[nomer] = time.time()
            log.info("видео вложено в карточку %s: %d", nomer, len(roliki))
            if iz_kwargs:
                kwargs["media"] = novoe
            else:
                args = (args[0], novoe) + tuple(args[2:])
            return args, kwargs
    except Exception as e:
        log.warning("не вложил видео в альбом: %r", e)
    return args, kwargs


def _wrap_silent(orig):
    """answer_callback_query живёт секунды: не повторяем и не роняем обработчик."""

    @functools.wraps(orig)
    async def inner(self, *args, **kwargs):
        kwargs.setdefault("read_timeout", 10)
        kwargs.setdefault("write_timeout", 10)
        kwargs.setdefault("connect_timeout", 10)
        kwargs.setdefault("pool_timeout", 10)
        try:
            return await orig(self, *args, **kwargs)
        except TypeError:
            for k in ("read_timeout", "write_timeout", "connect_timeout", "pool_timeout"):
                kwargs.pop(k, None)
            try:
                return await orig(self, *args, **kwargs)
            except Exception:
                return True
        except Exception as e:
            log.warning("не подтвердили нажатие кнопки, идём дальше: %r", e)
            return True

    inner._ns_wrapped = True
    return inner


ALBUM_PAUSE = 0.3


def patch_card_html_budget():
    """Делаем HTML-файл лёгким: он собирается долго только из-за веса."""
    try:
        sys.path.insert(0, BASE)
        import card_html
    except Exception:
        return
    changed = []
    for name in dir(card_html):
        if name.startswith("_") or not name.isupper():
            continue
        try:
            value = getattr(card_html, name)
        except Exception:
            continue
        if not isinstance(value, int) or isinstance(value, bool):
            continue
        if "BUDGET" in name or "LIMIT_BYTES" in name or "MAX_BYTES" in name:
            if value > 6 * 1024 * 1024:
                setattr(card_html, name, 6 * 1024 * 1024)
                changed.append(name)
    if changed:
        log.info("HTML облегчён, правила: %s", ", ".join(changed))


def patch_bot_methods():
    """Повторы отправки при обрыве связи."""
    from telegram import Bot
    from telegram.error import TimedOut, NetworkError, RetryAfter

    errors = (TimedOut, NetworkError, RetryAfter)

    # ВАЖНО: ExtBot наследуется от Bot. Если обернуть оба класса,
    # повторы вкладываются друг в друга: 4 попытки превращаются в 16.
    # Поэтому Bot трогаем только там, где ExtBot своего метода не имеет.
    ext = None
    try:
        from telegram.ext import ExtBot
        ext = ExtBot
    except Exception:
        ext = None

    n = 0
    for name in TEXT_METHODS + MEDIA_METHODS + SILENT_METHODS:
        target = None
        if ext is not None and name in ext.__dict__:
            target = ext
        elif name in Bot.__dict__:
            target = Bot
        if target is None:
            continue
        orig = target.__dict__.get(name)
        if orig is None or getattr(orig, "_ns_wrapped", False):
            continue
        if name in SILENT_METHODS:
            setattr(target, name, _wrap_silent(orig))
        else:
            setattr(target, name, _wrap_send(orig, name in MEDIA_METHODS, errors))
        n += 1
    log.info("защищено методов отправки: %d", n)


def patch_error_handlers():
    """Сетевые таймауты не уходят владельцу как «Сбой во внутреннем боте»."""
    from telegram.ext import Application
    from telegram.error import TimedOut, NetworkError

    orig = Application.add_error_handler
    if getattr(orig, "_ns_wrapped", False):
        return

    def filtered(callback):
        @functools.wraps(callback)
        async def inner(update, context):
            err = getattr(context, "error", None)
            if isinstance(err, (TimedOut, NetworkError)):
                log.warning("сетевая ошибка не показана владельцу: %r", err)
                return
            return await callback(update, context)

        inner._ns_filtered = True
        return inner

    @functools.wraps(orig)
    def inner(self, callback, block=True, *args, **kwargs):
        if not getattr(callback, "_ns_filtered", False):
            callback = filtered(callback)
        try:
            return orig(self, callback, block, *args, **kwargs)
        except TypeError:
            return orig(self, callback)

    inner._ns_wrapped = True
    Application.add_error_handler = inner
    log.info("фильтр сетевых ошибок включён")


# --- условия 50/50 для авто, которое уже в Грузии --------------------------
#
# Пока авто едет — схема 50 % по договору / 50 % по прибытии в Грузию.
# Когда авто в Грузии — этой строки быть не должно, там предоплата 500 $.

import re
import sqlite3
import shutil

# признаки того, что речь про авто, уже стоящее в Грузии
GEO_MARKERS = ("Предоплата", "Авто в Грузии", "в Грузии")

# предложение про 50/50 — в любых написаниях (50%, 50 %, 50 процентов)
SPLIT_RE = re.compile(
    r"[^.\n!]*50\s*%[^.\n!]*(?:договор|прибыт)[^.\n!]*[.!]?",
    re.IGNORECASE,
)


def clean_split(text):
    """Убирает фразу про 50/50, если авто уже в Грузии."""
    if not text or "50" not in text:
        return text
    if not any(m in text for m in GEO_MARKERS):
        return text
    if "Предоплата" not in text and "Авто в Грузии" not in text:
        return text
    new = SPLIT_RE.sub("", text)
    if new == text:
        return text
    new = re.sub(r"[ \t]{2,}", " ", new)
    new = re.sub(r"\n{3,}", "\n\n", new)
    new = re.sub(r"[ \t]+\n", "\n", new)
    return new.strip()


def fix_split_text(method_name, args, kwargs):
    """Чистит text/caption прямо перед отправкой."""
    try:
        for key in ("text", "caption"):
            if key in kwargs and isinstance(kwargs[key], str):
                kwargs[key] = clean_split(kwargs[key])
        # send_message(chat_id, text) — текст может идти вторым по счёту
        if method_name in ("send_message", "edit_message_text") and len(args) >= 2:
            if isinstance(args[1], str):
                args = list(args)
                args[1] = clean_split(args[1])
                args = tuple(args)
    except Exception as e:
        log.warning("не удалось почистить текст: %r", e)
    return args, kwargs


def db_clean_split():
    """Разово вычищает фразу 50/50 из описаний машин, стоящих в Грузии."""
    db = os.path.join(BASE, "crm.db")
    if not os.path.exists(db):
        return
    try:
        con = sqlite3.connect(db)
        cur = con.cursor()
        cols = [r[1] for r in cur.execute("PRAGMA table_info(cars)").fetchall()]
        if "condition_text" not in cols:
            con.close()
            return

        keys = ["rowid", "condition_text"]
        for extra in ("status", "stage"):
            if extra in cols:
                keys.append(extra)
        rows = cur.execute("SELECT %s FROM cars" % ", ".join(keys)).fetchall()

        changed = []
        for row in rows:
            data = dict(zip(keys, row))
            text = data.get("condition_text") or ""
            if "50" not in text:
                continue
            status = str(data.get("status") or "")
            stage = data.get("stage")
            in_georgia = ("Грузи" in status) or (
                isinstance(stage, int) and stage >= 3
            )
            if not in_georgia:
                continue
            new = SPLIT_RE.sub("", text)
            new = re.sub(r"\n{3,}", "\n\n", new).strip()
            if new != text:
                changed.append((new, data["rowid"]))

        if changed:
            shutil.copy2(db, db + ".bak_split")
            cur.executemany(
                "UPDATE cars SET condition_text = ? WHERE rowid = ?", changed
            )
            con.commit()
            log.info("описание почищено от 50/50 у карточек: %d", len(changed))
        con.close()
    except Exception as e:
        log.warning("чистка базы не удалась: %r", e)


# --- свой экран «Как видит покупатель» -------------------------------------
#
# Работает независимо от кнопок в cars_ui: команда /pokaz в CRM-боте
# показывает список карточек, по нажатию рисует карточку ровно так,
# как её видит покупатель — фото сверху, текст, видео снизу.

import json

PHONE = "[N]"
WHATSAPP = "[URL]"
ADDRESS = "Киев, улица Победы 20"
MAPS = "[URL]"
PREPAY = "500 $"
DAYS_AFTER_PAY = 14

CAR_FIELDS = (
    "auto_number", "brand", "model", "year", "vin", "fuel", "engine_cc",
    "gearbox", "drive", "mileage_km", "color", "condition_text", "diag_link",
    "status", "sea_container", "price_uah", "published", "eta_manual",
    "photos", "videos", "hidden_photos",
)


def _rows(query, params=()):
    db = os.path.join(BASE, "crm.db")
    con = sqlite3.connect(db)
    con.row_factory = sqlite3.Row
    try:
        return [dict(r) for r in con.execute(query, params).fetchall()]
    finally:
        con.close()


def _car_columns():
    db = os.path.join(BASE, "crm.db")
    con = sqlite3.connect(db)
    try:
        return [r[1] for r in con.execute("PRAGMA table_info(cars)").fetchall()]
    finally:
        con.close()


def _ids(value):
    """Достаёт список file_id из колонки, в каком бы виде она ни хранилась."""
    if not value:
        return []
    if isinstance(value, (list, tuple)):
        items = list(value)
    else:
        text = str(value).strip()
        items = None
        if text.startswith("[") or text.startswith("{"):
            try:
                data = json.loads(text)
                if isinstance(data, dict):
                    data = list(data.values())
                items = data
            except Exception:
                items = None
        if items is None:
            items = re.split(r"[\s,;|]+", text)
    out = []
    for it in items:
        if isinstance(it, dict):
            it = it.get("file_id") or it.get("id") or ""
        it = str(it).strip().strip('"').strip("'")
        if len(it) > 20:
            out.append(it)
    return out


def _money(value):
    try:
        n = int(float(value))
    except (TypeError, ValueError):
        return "—"
    return "{:,}".format(n).replace(",", " ") + " $"


def _dash(value):
    value = "" if value is None else str(value).strip()
    return value if value else "—"


def client_text(car):
    """Текст карточки глазами покупателя."""
    status = str(car.get("status") or "")
    in_georgia = "Грузи" in status

    title = " ".join(x for x in [car.get("brand"), car.get("model")] if x) or "Автомобиль"
    lines = []
    lines.append("UA ART COMPANY LLC")
    lines.append("")
    lines.append("%s %s" % (title, _dash(car.get("year"))))
    lines.append("Номер: %s" % _dash(car.get("auto_number")))
    lines.append("VIN: %s" % _dash(car.get("vin")))
    lines.append("")
    lines.append("ХАРАКТЕРИСТИКИ")
    lines.append("Топливо: %s" % _dash(car.get("fuel")))
    lines.append("Объём: %s" % _dash(car.get("engine_cc")))
    lines.append("КПП: %s" % _dash(car.get("gearbox")))
    lines.append("Привод: %s" % _dash(car.get("drive")))
    lines.append("Пробег: %s" % _dash(car.get("mileage_km")))
    lines.append("Цвет: %s" % _dash(car.get("color")))
    if car.get("diag_link"):
        lines.append("Диагностика: %s" % car["diag_link"])
    if car.get("condition_text"):
        lines.append("")
        lines.append("ОПИСАНИЕ")
        lines.append(str(car["condition_text"]).strip())
    lines.append("")
    lines.append("СТАТУС")
    lines.append(_dash(status))
    if not in_georgia and car.get("sea_container"):
        lines.append("Контейнер: %s" % car["sea_container"])
    lines.append("")
    lines.append("ЦЕНА")
    lines.append(_money(car.get("price_uah")))
    lines.append("")
    lines.append("УСЛОВИЯ")
    lines.append("Доставка, растаможка и сертификация включены в стоимость.")
