# --- порядок в папке: делается автоматически при каждом старте -------------

STAROE = os.path.join(BASE, "staroe")

# одноразовые скрипты, которые уже отработали — им место в архиве
MUSOR = (
    "apply_", "fix2", "fix3", "fix4", "fixkey", "setkey", "writekey",
    "setup_key", "ustanovka", "migrate", "arhiv_migraciya", "c.py",
    "diagnostika", "kod2", "team_bot.txt",
)
MUSOR_KONCY = (".bak_", "_backup_", ".py.bak", "crm_backup_", "crm.db.bak")

# эти не трогаем никогда
SVYATOE = (
    "run_all.py", "start_safe.py", "team_bot.py", "lead_bot.py", "db.py",
    "ai.py", "ai_filter.py", "assistant.py", "cars_ui.py", "cars_schema.py",
    "client_ui.py", "client_style.py", "card_render.py", "card_html.py",
    "photo_hide.py", "visits.py", "voice.py", "proverka.py", "crm.db",
)


def _v_arhiv(name, reason):
    try:
        os.makedirs(STAROE, exist_ok=True)
        dst = os.path.join(STAROE, name)
        if os.path.exists(dst):
            base, ext = os.path.splitext(name)
            dst = os.path.join(STAROE, "%s_%d%s" % (base, int(time.time()), ext))
        shutil.move(os.path.join(BASE, name), dst)
        log.info("в архив: %s (%s)", name, reason)
        return True
    except Exception as e:
        log.warning("не убрался %s: %r", name, e)
        return False


def pochinit_imena():
    """Айфон подставляет пробел вместо подчёркивания — чиним сами."""
    nado_restart = []
    try:
        files = os.listdir(BASE)
    except Exception:
        return nado_restart

    for name in files:
        if " " not in name or not name.endswith(".py"):
            continue
        pravilno = name.replace(" ", "_")
        src = os.path.join(BASE, name)
        dst = os.path.join(BASE, pravilno)
        try:
            if not os.path.exists(dst):
                shutil.move(src, dst)
                log.info("имя исправлено: «%s» -> %s", name, pravilno)
                nado_restart.append(pravilno)
                continue
            # оба есть — оставляем свежий, старый в архив
            if os.path.getmtime(src) > os.path.getmtime(dst):
                _v_arhiv(pravilno, "заменён более свежей версией")
                shutil.move(src, dst)
                log.info("«%s» новее — стал %s", name, pravilno)
                nado_restart.append(pravilno)
            else:
                _v_arhiv(name, "дубль с пробелом, версия старая")
        except Exception as e:
            log.warning("не переименовался %s: %r", name, e)
    return nado_restart


def ubrat_musor():
    """Отработавшие скрипты и бэкапы уезжают в папку staroe."""
    ubrano = 0
    try:
        files = os.listdir(BASE)
    except Exception:
        return 0
    for name in files:
        if name in SVYATOE or name.startswith("."):
            continue
        path = os.path.join(BASE, name)
        if not os.path.isfile(path):
            continue
        musor = name.startswith(MUSOR) or any(k in name for k in MUSOR_KONCY)
        if musor and _v_arhiv(name, "отработал"):
            ubrano += 1
    if ubrano:
        log.info("убрано в staroe: %d файлов", ubrano)
    return ubrano


def apply_all():
    ok = True
    for func in (
        patch_request_timeouts,
        patch_bot_methods,
        patch_error_handlers,
        patch_register_hook,
        patch_card_html_budget,
        patch_download_cache,
    ):
        try:
            func()
        except Exception as e:
            ok = False
            log.warning("не удалось применить %s: %r", func.__name__, e)
    return ok


# --- запуск ----------------------------------------------------------------

def _zhivoy_token(znachenie):
    """Проверяет токен у Telegram. Ничего не отправляет, только спрашивает."""
    if not znachenie:
        return False
    try:
        import urllib.request
        import json as _json
        adres = "[URL]" % znachenie
        with urllib.request.urlopen(adres, timeout=20) as otvet:
            return bool(_json.loads(otvet.read().decode("utf-8")).get("ok"))
    except Exception as e:
        log.warning("токен не проверился: %r", e)
        return None          # непонятно — считаем, что жив


def _token_iz(imya):
    try:
        with open(os.path.join(BASE, imya), "r", encoding="utf-8") as fh:
            return fh.read().strip()
    except Exception:
        return ""


def avariynyy_rezhim(zhivoy, slomannyy_fayl):
    """Один токен негоден — поднимаем только рабочего бота ради /token."""
    from telegram.ext import ApplicationBuilder

    log.warning("АВАРИЙНЫЙ РЕЖИМ: %s содержит негодный токен", slomannyy_fayl)
    app = ApplicationBuilder().token(zhivoy).build()
    register_token(app)

    async def pri_starte(application):
        try:
            hozyain = None
            put = os.path.join(BASE, "vladelec.txt")
            if os.path.exists(put):
                with open(put, "r", encoding="utf-8") as fh:
                    hozyain = int(fh.read().strip())
            if hozyain:
                await application.bot.send_message(
                    hozyain,
                    "Один из ботов не поднялся: в файле %s негодный токен.\n\n"
                    "Пришли новый сюда одной командой:\n/token НОВЫЙ_ТОКЕН\n\n"
                    "Я сам пойму, чей он. Потом Tasks → Restart." % slomannyy_fayl)
        except Exception as e:
            log.warning("не предупредил владельца: %r", e)

    app.post_init = pri_starte
    app.run_polling(drop_pending_updates=True)


def main():
    # UA-TASK084-START-SINGLETON
    import fcntl as _v184_fcntl
    _v184_singleton = open(
        os.path.join(BASE, ".start_safe.singleton.lock"), "a+", encoding="utf-8")
    try:
        _v184_fcntl.flock(
            _v184_singleton.fileno(), _v184_fcntl.LOCK_EX | _v184_fcntl.LOCK_NB)
    except BlockingIOError:
        log.warning("start_safe.py уже запущен; второй экземпляр остановлен")
        return
    if not os.path.exists(TARGET):
        log.error("не найден %s — проверь имя файла", TARGET)
        raise SystemExit(1)

    os.chdir(BASE)
    if BASE not in sys.path:
        sys.path.insert(0, BASE)

    novye = pochinit_imena()
    ubrat_musor()
    if novye:
        log.warning("обновились файлы: %s — если что-то ведёт себя странно, "
                    "нажми Restart ещё раз", ", ".join(novye))

    apply_all()
    db_clean_split()

    # проверяем токены до запуска: один битый больше не роняет обоих
    klient = _token_iz("bot_token.txt")
    krm = _token_iz("team_token.txt")
    ok_klient = _zhivoy_token(klient)
    ok_krm = _zhivoy_token(krm)

    if ok_krm is False and ok_klient is not False:
        avariynyy_rezhim(klient, "team_token.txt")
        return
    if ok_klient is False and ok_krm is not False:
        avariynyy_rezhim(krm, "bot_token.txt")
        return
    if ok_klient is False and ok_krm is False:
        log.error("оба токена негодны — впиши их в bot_token.txt и team_token.txt")

    log.info("защита включена, запускаю run_all.py")

    while True:
        try:
            runpy.run_path(TARGET, run_name="__main__")
            log.warning("run_all.py завершился сам, перезапуск через 10 c")
        except SystemExit:
            raise
        except KeyboardInterrupt:
            raise
        except Exception as e:
            tekst = "%r" % e
            if "InvalidToken" in tekst or "Unauthorized" in tekst:
                # какой именно токен отвергли — видно в тексте ошибки
                klient = _token_iz("bot_token.txt")
                krm = _token_iz("team_token.txt")
                if klient and klient in tekst and krm and krm not in tekst:
                    avariynyy_rezhim(krm, "bot_token.txt")
                    return
                if krm and krm in tekst and klient and klient not in tekst:
                    avariynyy_rezhim(klient, "team_token.txt")
                    return
                log.error("Оба токена не приняты. Впиши действующие в "
                          "bot_token.txt и team_token.txt через редактор.")
                time.sleep(60)
                continue
            log.exception("run_all.py упал: %r — перезапуск через 10 c", e)
        time.sleep(10)


if __name__ == "__main__":
    main()

